/**
 * MARK — Initialize Run Metrics
 * Version: 2.0.0
 * n8n Code node mode: Run Once for All Items
 *
 * The Schedule Trigger owns cadence. This node always opens a run summary and
 * never blocks manual or scheduled execution with an additional time gate.
 */

const SCHEDULER_VERSION = '2.0.0';
const STATE_SCHEMA = 'mark.workflow_state.v1';
const INTERVAL_MINUTES = 10;
const MAX_RUN_SUMMARIES = 50;

const inputItems = $input.all();
const staticData = $getWorkflowStaticData('global');
const root = staticData.mark_job_hunter ?? (staticData.mark_job_hunter = {});

root.schema_version = STATE_SCHEMA;
root.runs ??= {};
root.errors ??= [];
root.vacancies ??= {};
root.provider_health ??= {};

const now = Date.now();
const startedAt = new Date(now).toISOString();
const previousScheduler = root.scheduler && typeof root.scheduler === 'object'
  ? root.scheduler
  : {};
let emptyRunStreak = Number(previousScheduler.empty_run_streak ?? 0);
let lastCompletedRunId = previousScheduler.last_completed_run_id ?? null;

const previousRun = root.current_run_id ? root.runs[root.current_run_id] : null;
if (previousRun && !previousRun.finished_observed_at) {
  const aiCandidates = Number(previousRun.ai_candidates_count ?? 0);
  const operationalErrors =
    Number(previousRun.source_error_count ?? 0) +
    Number(previousRun.provider_errors_count ?? 0);

  previousRun.finished_observed_at = startedAt;
  previousRun.run_outcome = operationalErrors > 0
    ? 'operational_error'
    : aiCandidates > 0
      ? 'ai_candidates_found'
      : 'clean_empty';

  if (operationalErrors === 0 && aiCandidates === 0) {
    emptyRunStreak += 1;
  } else if (aiCandidates > 0) {
    emptyRunStreak = 0;
  }
  lastCompletedRunId = previousRun.run_id ?? root.current_run_id;
}

const runSequence = Number(previousScheduler.run_sequence ?? 0) + 1;
const runKind = 'interval_10m';
const runId = `${startedAt}_${runKind}_${runSequence}`;

// Replace the legacy scheduler object so obsolete 5/30-minute gate fields do
// not survive in workflow static data.
root.scheduler = {
  mode: 'fixed_interval',
  scheduler_version: SCHEDULER_VERSION,
  interval_minutes: INTERVAL_MINUTES,
  run_sequence: runSequence,
  empty_run_streak: emptyRunStreak,
  last_completed_run_id: lastCompletedRunId,
  last_started_at: startedAt,
  last_run_kind: runKind,
};
root.current_run_id = runId;

root.runs[runId] = {
  run_id: runId,
  run_kind: runKind,
  scheduler_version: SCHEDULER_VERSION,
  schedule_interval_minutes: INTERVAL_MINUTES,
  started_at: startedAt,
  empty_run_streak_at_start: emptyRunStreak,
  rss_items: 0,
  new_guid_count: 0,
  source_skipped_count: 0,
  source_processed_count: 0,
  source_error_count: 0,
  prefilter_pass: 0,
  hard_filter_pass: 0,
  level_pass_or_stretch: 0,
  ai_candidates_count: 0,
  ai_scored_count: 0,
  telegram_sent_count: 0,
  provider_errors_count: 0,
  nvidia_admitted_count: 0,
  nvidia_deferred_count: 0,
  by_source: {},
};

const runIds = Object.keys(root.runs).sort((left, right) => {
  const leftTime = Date.parse(root.runs[left]?.started_at ?? '') || 0;
  const rightTime = Date.parse(root.runs[right]?.started_at ?? '') || 0;
  return leftTime - rightTime || left.localeCompare(right);
});
const staleRunIds = runIds
  .filter((candidateRunId) => candidateRunId !== runId)
  .slice(0, Math.max(0, runIds.length - MAX_RUN_SUMMARIES));
for (const staleRunId of staleRunIds) {
  delete root.runs[staleRunId];
}

const seed = inputItems[0] ?? { json: {} };
return [{
  ...seed,
  json: {
    ...(seed.json ?? {}),
    workflow_state_schema: STATE_SCHEMA,
    scheduler_version: SCHEDULER_VERSION,
    scheduler_mode: 'fixed_interval',
    schedule_interval_minutes: INTERVAL_MINUTES,
    run_id: runId,
    run_kind: runKind,
    empty_run_streak: emptyRunStreak,
    run_started_at: startedAt,
  },
}];

/**
 * MARK — HeadHunter Search Requests
 * Version: 1.1.0
 * n8n Code node mode: Run Once for All Items
 *
 * Builds two bounded searches:
 *   1. remote AI vacancies on hh.ru;
 *   2. all AI vacancies in Tbilisi on headhunter.ge.
 *
 * HH's `moreThan6` category is excluded server-side because it is always
 * outside MARK's accepted experience policy. The mixed `between3And6`
 * category stays in retrieval for downstream 3–4 vs confirmed 5+ analysis.
 * Salary is intentionally absent from the query.
 */

const HH_SEARCH_QUERY_VERSION = '1.1.0';
const HH_API_BASE_URL = 'https://api.hh.ru/vacancies';
const HH_ALLOWED_EXPERIENCE = [
  'noExperience',
  'between1And3',
  'between3And6',
];
const HH_TEXT_QUERY = [
  '"AI Engineer"',
  '"LLM Engineer"',
  '"ML Engineer"',
  '"Machine Learning Engineer"',
  '"AI Developer"',
  '"Data Scientist"',
  '"Prompt Engineer"',
  '"ИИ инженер"',
  '"ML разработчик"',
  'RAG',
].join(' OR ');

function searchUrl({ scope, host, area = null, workFormat = null }) {
  // n8n's Code-node sandbox does not expose the Web API URLSearchParams.
  // Build the query from ECMAScript globals that are available there.
  const parameters = {
    text: HH_TEXT_QUERY,
    per_page: '100',
    page: '0',
    period: '1',
    order_by: 'publication_time',
    no_magic: 'true',
    experience: HH_ALLOWED_EXPERIENCE,
    host,
    locale: 'RU',
    ...(area ? { area } : {}),
    ...(workFormat ? { work_format: workFormat } : {}),
  };
  const query = Object.entries(parameters)
    .flatMap(([key, value]) => (Array.isArray(value) ? value : [value])
      .map((item) => `${encodeURIComponent(key)}=${encodeURIComponent(item)}`))
    .join('&');

  return {
    json: {
      source: 'headhunter',
      hh_search_query_version: HH_SEARCH_QUERY_VERSION,
      hh_search_scope: scope,
      hh_search_url: `${HH_API_BASE_URL}?${query}`,
      salary_filter_applied: false,
    },
  };
}

return [
  searchUrl({
    scope: 'remote',
    host: 'hh.ru',
    workFormat: 'REMOTE',
  }),
  searchUrl({
    scope: 'tbilisi',
    host: 'headhunter.ge',
    area: '2758',
  }),
];

/**
 * MARK — HeadHunter Search Response Parser
 * Version: 1.0.0
 * n8n Code node mode: Run Once for All Items
 */

const HH_SEARCH_RESPONSE_VERSION = '1.0.0';

function text(value) {
  return String(value ?? '').trim();
}

function stripHtml(value) {
  return text(value)
    .replace(/<br\s*\/?\s*>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function responseBody(json) {
  return json && typeof json.body === 'object' && json.body !== null
    ? json.body
    : json;
}

function workFormatIds(value) {
  return Array.isArray(value)
    ? value.map((item) => text(item?.id)).filter(Boolean)
    : [];
}

const output = [];
const seen = new Set();

for (const inputItem of $input.all()) {
  const response = inputItem?.json ?? {};
  const statusCode = Number(response.statusCode ?? 200);
  const body = responseBody(response);

  if (statusCode < 200 || statusCode >= 300 || !body || !Array.isArray(body.items)) {
    const errorType = text(body?.errors?.[0]?.type || body?.description || 'invalid_response');
    throw new Error(`HH search failed (${statusCode}): ${errorType}`);
  }

  for (const vacancy of body.items) {
    const sourceId = text(vacancy?.id);
    if (!sourceId || seen.has(sourceId)) continue;
    seen.add(sourceId);

    const requirement = stripHtml(vacancy?.snippet?.requirement);
    const responsibility = stripHtml(vacancy?.snippet?.responsibility);
    const areaName = text(vacancy?.area?.name);
    const apiUrl = text(vacancy?.url) || `https://api.hh.ru/vacancies/${sourceId}`;
    const publicUrl = text(vacancy?.alternate_url) || `https://hh.ru/vacancy/${sourceId}`;
    const formats = workFormatIds(vacancy?.work_format);

    output.push({
      json: {
        source: 'headhunter',
        source_id: sourceId,
        source_guid: `hh:${sourceId}`,
        source_state_key: `hh:${sourceId}`,
        vacancy_key: `hh:${sourceId}`,
        api_url: apiUrl,
        url: publicUrl,
        title: text(vacancy?.name),
        company: text(vacancy?.employer?.name),
        location: areaName,
        city: areaName,
        description_snippet: [requirement, responsibility].filter(Boolean).join(' '),
        hh_preview_experience_id: text(vacancy?.experience?.id),
        hh_preview_experience_name: text(vacancy?.experience?.name),
        hh_preview_work_format_ids: formats,
        published_at: text(vacancy?.published_at),
        created_at: text(vacancy?.created_at),
        salary: vacancy?.salary_range ?? vacancy?.salary ?? null,
        hh_search_response_version: HH_SEARCH_RESPONSE_VERSION,
        salary_filter_applied: false,
      },
      pairedItem: inputItem?.pairedItem,
    });
  }
}

return output;

/**
 * MARK — Run Metrics
 * Version: 1.1.0
 * n8n Code node mode: Run Once for All Items
 *
 * The same source is embedded in four metric nodes. Item contract fields
 * identify the stage, so branch execution order cannot misclassify a metric.
 */

const METRICS_VERSION = '1.1.0';
const items = $input.all();
const staticData = $getWorkflowStaticData('global');
const root = staticData.mark_job_hunter ?? (staticData.mark_job_hunter = {});
root.runs ??= {};

const jsonItems = items.map((item) => item?.json ?? {});
let metric = 'rss_items';
if (jsonItems.some((json) => Object.prototype.hasOwnProperty.call(json, 'level_decision'))) {
  metric = 'level_pass_or_stretch';
} else if (jsonItems.some((json) => Object.prototype.hasOwnProperty.call(json, 'hard_filter_decision'))) {
  metric = 'hard_filter_pass';
} else if (jsonItems.some((json) => Object.prototype.hasOwnProperty.call(json, 'prefilter_decision'))) {
  metric = 'prefilter_pass';
}

const run = root.current_run_id ? root.runs[root.current_run_id] : null;
if (run && metric) {
  run.by_source ??= {};
  const source = jsonItems.some((json) => {
    const value = String(json.source ?? '').toLowerCase();
    return value === 'headhunter' || value === 'hh' || String(json.vacancy_key ?? '').startsWith('hh:');
  }) ? 'headhunter' : 'habr';
  run.by_source[source] ??= {};
  run.by_source[source][metric] = items.length;
  run[metric] = Object.values(run.by_source)
    .reduce((total, sourceMetrics) => total + Number(sourceMetrics?.[metric] ?? 0), 0);
  run.metrics_version = METRICS_VERSION;
  run.last_metric_at = new Date().toISOString();
}

return items;

/**
 * MARK — Durable Source Gate
 * Version: 1.2.0
 * n8n Code node mode: Run Once for All Items
 *
 * Prevents the same RSS vacancy from being fetched on every execution. New,
 * due-for-retry, and stale in-progress items pass; completed and terminally
 * failed items stay tracked and are skipped.
 */

const SOURCE_GATE_VERSION = '1.2.0';
const STATE_SCHEMA = 'mark.workflow_state.v1';
const PROCESSING_STALE_MS = 20 * 60 * 1000;
const RETENTION_MS = 60 * 24 * 60 * 60 * 1000;
const MAX_SOURCE_ITEMS = 2000;

const inputItems = $input.all();
const staticData = $getWorkflowStaticData('global');
const root = staticData.mark_job_hunter ?? (staticData.mark_job_hunter = {});

root.schema_version = STATE_SCHEMA;
root.source_items ??= {};
root.vacancies ??= {};
root.runs ??= {};
root.errors ??= [];

const now = Date.now();
const nowIso = new Date(now).toISOString();

function value(...candidates) {
  for (const candidate of candidates) {
    const normalized = String(candidate ?? '').trim();
    if (normalized) return normalized;
  }
  return '';
}

function sourceKey(json) {
  const annotated = value(json.source_state_key);
  if (annotated) return annotated;

  const raw = value(
    json.source_guid,
    json.guid,
    json.vacancy_key,
    json.source_id,
    json.link,
    json.url,
  );
  if (!raw) return '';
  if (/^(?:habr|hh):/i.test(raw)) return raw.toLowerCase().startsWith('hh:') ? `hh:${raw.slice(3)}` : raw;

  const source = value(json.source).toLowerCase();
  const namespace = source === 'headhunter' || source === 'hh' || /(?:api\.)?hh\.ru|headhunter\.ge/i.test(raw)
    ? 'hh'
    : 'habr';
  return `${namespace}:${raw}`;
}

if (now - Number(root.last_source_prune_at_ms ?? 0) > 24 * 60 * 60 * 1000) {
  const records = Object.entries(root.source_items)
    .map(([key, record]) => ({
      key,
      updated: Date.parse(record.updated_at ?? record.first_seen_at ?? 0) || 0,
    }))
    .sort((a, b) => b.updated - a.updated);

  for (const entry of records) {
    if (entry.updated > 0 && now - entry.updated > RETENTION_MS) {
      delete root.source_items[entry.key];
    }
  }

  const remaining = Object.entries(root.source_items)
    .map(([key, record]) => ({
      key,
      updated: Date.parse(record.updated_at ?? record.first_seen_at ?? 0) || 0,
    }))
    .sort((a, b) => b.updated - a.updated);
  for (const entry of remaining.slice(MAX_SOURCE_ITEMS)) {
    delete root.source_items[entry.key];
  }
  root.last_source_prune_at_ms = now;
}

const output = [];
let skipped = 0;

for (const item of inputItems) {
  const json = item?.json ?? {};
  const key = sourceKey(json);

  if (!key) {
    output.push({
      ...item,
      json: {
        ...json,
        workflow_state_schema: STATE_SCHEMA,
        source_gate_version: SOURCE_GATE_VERSION,
        source_state_key: null,
        source_state_action: 'process',
        source_state_reason: 'missing_key_untracked',
      },
    });
    continue;
  }

  const record = root.source_items[key];
  const updatedAt = Date.parse(record?.updated_at ?? 0) || 0;
  const retryDue = record?.status === 'retry' && Number(record.next_retry_at_ms ?? 0) <= now;
  const staleProcessing = record?.status === 'processing' && now - updatedAt >= PROCESSING_STALE_MS;
  const vacancyRecord = record?.vacancy_key ? root.vacancies[record.vacancy_key] : null;
  const downstreamRecoveryDue = Boolean(vacancyRecord) && (
    (
      vacancyRecord.scoring_status === 'error' &&
      Number(vacancyRecord.next_retry_at_ms ?? 0) <= now
    ) ||
    (
      vacancyRecord.scoring_status === 'completed' &&
      vacancyRecord.delivery_required === true &&
      vacancyRecord.telegram_sent !== true
    ) ||
    (
      vacancyRecord.scoring_status === 'pending' &&
      now - (Date.parse(vacancyRecord.updated_at ?? 0) || 0) >= PROCESSING_STALE_MS
    )
  );
  const shouldProcess = !record || retryDue || staleProcessing || downstreamRecoveryDue;

  if (!shouldProcess) {
    skipped += 1;
    continue;
  }

  const reason = !record
    ? 'new_source_item'
    : retryDue
      ? 'source_retry_due'
      : staleProcessing
        ? 'stale_source_processing_recovery'
        : 'downstream_recovery_due';

  root.source_items[key] = {
    ...(record ?? {}),
    key,
    status: 'processing',
    attempts: Number(record?.attempts ?? 0) + 1,
    first_seen_at: record?.first_seen_at ?? nowIso,
    updated_at: nowIso,
    next_retry_at_ms: 0,
    last_reason: reason,
  };

  output.push({
    ...item,
    json: {
      ...json,
      workflow_state_schema: STATE_SCHEMA,
      source_gate_version: SOURCE_GATE_VERSION,
      source_state_key: key,
      source_state_action: 'process',
      source_state_reason: reason,
    },
  });
}

const run = root.current_run_id ? root.runs[root.current_run_id] : null;
if (run) {
  const source = inputItems.some((item) => {
    const json = item?.json ?? {};
    const name = value(json.source).toLowerCase();
    return name === 'headhunter' || name === 'hh' || sourceKey(json).startsWith('hh:');
  }) ? 'headhunter' : 'habr';
  run.by_source ??= {};
  run.by_source[source] ??= {};
  run.by_source[source].new_guid_count = output.length;
  run.by_source[source].source_skipped_count = skipped;
  run.new_guid_count = Object.values(run.by_source)
    .reduce((total, metrics) => total + Number(metrics?.new_guid_count ?? 0), 0);
  run.source_skipped_count = Object.values(run.by_source)
    .reduce((total, metrics) => total + Number(metrics?.source_skipped_count ?? 0), 0);
  run.last_source_gate_at = nowIso;
}

return output;

/**
 * MARK — HeadHunter Search Result Pre-filter
 * Version: 1.0.0
 * n8n Code node mode: Run Once for Each Item
 *
 * Only explicit Senior+/5+ and clearly off-target roles are rejected here.
 * Ambiguous results remain REVIEW so useful vacancies are not lost before the
 * full vacancy contract is available.
 */

const HH_PREFILTER_VERSION = '1.0.0';

function text(value) {
  return String(value ?? '').trim();
}

function normalized(value) {
  return text(value)
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[–—−]/g, '-')
    .replace(/\s+/g, ' ')
    .trim();
}

function unique(values) {
  return [...new Set(values.filter(Boolean))];
}

function experienceHint(id) {
  switch (text(id)) {
    case 'noExperience': return { min: 0, max: 0 };
    case 'between1And3': return { min: 1, max: 3 };
    case 'between3And6': return { min: 3, max: 6 };
    case 'moreThan6': return { min: 6, max: null };
    default: return { min: null, max: null };
  }
}

const inputItem = $input.item;
const vacancy = inputItem?.json ?? {};
const title = normalized(vacancy.title);
const snippet = normalized(vacancy.description_snippet);
const searchable = `${title} ${snippet}`;

const highLevelSignals = [
  { name: 'Senior', regex: /(?:^|[^\p{L}])(?:senior|sr\.?|сеньор|старш\p{L}*)(?=$|[^\p{L}])/iu },
  { name: 'Lead', regex: /(?:^|[^\p{L}])(?:lead|team[\s-]*lead|tech[\s-]*lead|лид|ведущ\p{L}*)(?=$|[^\p{L}])/iu },
  { name: 'Principal', regex: /(?:^|[^\p{L}])principal(?=$|[^\p{L}])/iu },
  { name: 'Staff', regex: /(?:^|[^\p{L}])staff(?=$|[^\p{L}])/iu },
  { name: 'Head', regex: /(?:^|[^\p{L}])(?:head|руководител\p{L}*)(?=$|[^\p{L}])/iu },
  { name: 'Architect', regex: /(?:^|[^\p{L}])(?:architect|архитектор\p{L}*)(?=$|[^\p{L}])/iu },
];

const offTargetSignals = [
  { name: 'Product Manager', regex: /\b(?:product|project|account)[\s-]*manager\b|(?:продуктов\p{L}*|проектн\p{L}*)\s+менеджер/iu },
  { name: 'Sales/Marketing', regex: /\b(?:sales|marketing)[\s-]*(?:manager|specialist)\b|(?:продаж|маркетолог|маркетинг)/iu },
  { name: 'Recruiting/HR', regex: /\b(?:recruiter|talent acquisition|hr[\s-]*manager)\b|(?:рекрутер|кадров)/iu },
  { name: 'Analyst', regex: /(?:бизнес|системн|data|данн\p{L}*)[\s-]*аналитик|\b(?:business|system|data)[\s-]*analyst\b/iu },
  { name: 'Design/Support', regex: /\b(?:ux|ui)[\s/+-]*designer\b|(?:дизайнер|техническ\p{L}*\s+поддержк)/iu },
];

const targetSignals = [
  { name: 'AI Engineer', regex: /\b(?:ai|llm|gen[\s-]*ai|rag|nlp|ml)[\s-]*(?:engineer|developer)\b|(?:инженер|разработчик)[^\n]{0,50}(?:\bии\b|\bai\b|\bllm\b|ml)/iu },
  { name: 'Machine Learning Engineer', regex: /\b(?:machine learning|artificial intelligence)[\s-]*(?:engineer|developer)\b/iu },
  { name: 'Prompt Engineer', regex: /\bprompt[\s-]*(?:engineer|developer)\b|промпт[\s-]*инженер/iu },
  { name: 'Data Scientist', regex: /\bdata scientist\b|дат[аa][\s-]*сайентист/iu },
  { name: 'MLOps/LLMOps', regex: /\b(?:mlops|llmops)\b/iu },
];

const adjacentSignals = [
  { name: 'Python Developer', regex: /\bpython[\s-]*(?:developer|engineer)\b|(?:python)[\s-]*разработчик/iu },
  { name: 'Backend Developer', regex: /\bback[\s-]*end[\s-]*(?:developer|engineer)\b|backend[\s-]*разработчик/iu },
  { name: 'Automation Engineer', regex: /\bautomation[\s-]*engineer\b|инженер[^\n]{0,30}автоматизац/iu },
];

const aiSignals = [
  { name: 'LLM', regex: /\bllms?\b|large language model|языков\p{L}*\s+модел/iu },
  { name: 'RAG', regex: /(?:^|[^a-z0-9_])rag(?:$|[^a-z0-9_])|retrieval[\s-]*augmented/iu },
  { name: 'AI Agents', regex: /\bai[\s-]*agents?\b|ии[\s-]*агент|агентн\p{L}*\s+систем/iu },
  { name: 'Generative AI', regex: /\bgen[\s-]*ai\b|generative[\s-]*ai|генеративн\p{L}*\s+(?:ии|модел)/iu },
  { name: 'Machine Learning', regex: /\bmachine learning\b|машинн\p{L}*\s+обучен/iu },
  { name: 'NLP', regex: /(?:^|[^a-z0-9_])nlp(?:$|[^a-z0-9_])|natural language processing/iu },
  { name: 'AI implementation', regex: /\b(?:langchain|langgraph|llamaindex|crewai|autogen|qdrant|embeddings?|vector database|openai|anthropic)\b/iu },
];

const high = highLevelSignals.filter((item) => item.regex.test(title)).map((item) => item.name);
const offTarget = offTargetSignals.filter((item) => item.regex.test(title)).map((item) => item.name);
const target = targetSignals.filter((item) => item.regex.test(title)).map((item) => item.name);
const adjacent = adjacentSignals.filter((item) => item.regex.test(title)).map((item) => item.name);
const ai = aiSignals.filter((item) => item.regex.test(searchable)).map((item) => item.name);
const experience = experienceHint(vacancy.hh_preview_experience_id);

let decision = 'REVIEW';
let code = 'review_ambiguous_hh_search_result';
let reasons = ['Search result requires full vacancy inspection'];

if (high.length > 0) {
  decision = 'REJECT';
  code = 'reject_explicit_senior_plus_title';
  reasons = [`Explicit high-level title: ${high.join(', ')}`];
} else if (experience.min !== null && experience.min >= 5) {
  decision = 'REJECT';
  code = 'reject_confirmed_5_plus_experience';
  reasons = [`HH experience category requires at least ${experience.min} years`];
} else if (offTarget.length > 0) {
  decision = 'REJECT';
  code = 'reject_explicit_off_target_title';
  reasons = [`Explicit off-target title: ${offTarget.join(', ')}`];
} else if (target.length > 0) {
  decision = 'PASS';
  code = 'pass_target_ai_title';
  reasons = [`Target role title: ${target.join(', ')}`];
} else if (adjacent.length > 0 && ai.length > 0) {
  decision = 'REVIEW';
  code = 'review_adjacent_role_with_ai_evidence';
  reasons = ['Adjacent engineering title contains AI evidence'];
} else if (ai.length > 0) {
  decision = 'REVIEW';
  code = 'review_ai_evidence_unknown_role';
  reasons = ['AI evidence exists, but the role title is ambiguous'];
}

return {
  ...inputItem,
  json: {
    ...vacancy,
    prefilter_version: HH_PREFILTER_VERSION,
    prefilter_decision: decision,
    prefilter_code: code,
    prefilter_reasons: reasons,
    prefilter_warnings: [],
    title_role_class: target.length > 0
      ? 'target'
      : adjacent.length > 0
        ? 'adjacent'
        : offTarget.length > 0
          ? 'off_target'
          : 'unknown',
    target_role_tier: target.length > 0 ? 'A' : adjacent.length > 0 ? 'B' : null,
    matched_target_roles: unique(target),
    matched_adjacent_roles: unique(adjacent),
    matched_absolute_off_target_roles: unique(offTarget),
    matched_soft_off_target_roles: [],
    matched_stack_off_target_roles: [],
    matched_core_ai_work_signals: unique(ai),
    matched_substantive_ai_categories: unique(ai),
    matched_ai_implementation_signals: unique(ai.filter((item) => item === 'AI implementation')),
    matched_level_categories: unique(high),
    matched_experience_signals: vacancy.hh_preview_experience_name
      ? [vacancy.hh_preview_experience_name]
      : [],
    experience_min_years_hint: experience.min,
    experience_max_years_hint: experience.max,
    should_fetch_full_vacancy: decision === 'PASS' || decision === 'REVIEW',
    salary_filter_applied: false,
  },
};

/**
 * MARK — HeadHunter Vacancy Normalizer
 * Version: 1.2.0
 * n8n Code node mode: Run Once for Each Item
 */

const HH_NORMALIZER_VERSION = '1.2.0';

function text(value) {
  return String(value ?? '').trim();
}

function stripHtml(value) {
  return text(value)
    .replace(/<br\s*\/?\s*>/gi, '\n')
    .replace(/<\/p\s*>/gi, '\n')
    .replace(/<\/li\s*>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n')
    .trim();
}

function stringArray(value, field = 'name') {
  if (!Array.isArray(value)) return [];
  return [...new Set(value.map((item) => text(item?.[field] ?? item)).filter(Boolean))];
}

function upstreamPreview() {
  try {
    return $('HH Search Result Pre-filter').item?.json ?? {};
  } catch {
    return {};
  }
}

function normalizedResponse(json) {
  if (json && typeof json.body === 'object' && json.body !== null) {
    return {
      statusCode: Number(json.statusCode ?? 200),
      body: json.body,
    };
  }
  return {
    statusCode: Number(json?.statusCode ?? 200),
    body: json,
  };
}

function experienceHint(id) {
  switch (text(id)) {
    case 'noExperience': return { min: 0, max: 0 };
    case 'between1And3': return { min: 1, max: 3 };
    case 'between3And6': return { min: 3, max: 6 };
    case 'moreThan6': return { min: 6, max: null };
    default: return { min: null, max: null };
  }
}

function workFormat(vacancy) {
  const ids = Array.isArray(vacancy?.work_format)
    ? vacancy.work_format.map((item) => text(item?.id).toUpperCase()).filter(Boolean)
    : [];
  const distinct = [...new Set(ids)];

  if (distinct.length > 1) {
    return { value: 'unknown', confidence: 'high', conflict: true, ids: distinct };
  }

  const mapped = {
    REMOTE: 'remote',
    HYBRID: 'hybrid',
    ON_SITE: 'office',
  }[distinct[0]];
  if (mapped) return { value: mapped, confidence: 'high', conflict: false, ids: distinct };

  if (text(vacancy?.schedule?.id).toLowerCase() === 'remote') {
    return { value: 'remote', confidence: 'medium', conflict: false, ids: ['legacy_schedule_remote'] };
  }

  return { value: 'unknown', confidence: 'low', conflict: false, ids: distinct };
}

function remoteEligibility(format, description) {
  if (format !== 'remote') {
    return { value: 'not_applicable', evidence: [] };
  }

  const searchable = text(description)
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[–—−]/g, '-')
    .replace(/\s+/g, ' ')
    .trim();
  const confirmedPatterns = [
    /\b(?:work|working)\s+from\s+anywhere\b/i,
    /\bworldwide\b|\banywhere\s+in\s+the\s+world\b/i,
    /\bremote\s+from\s+any\s+country\b/i,
    /(?:из\s+любой\s+точки\s+мира|из\s+любой\s+страны|по\s+всему\s+миру)/iu,
    /(?:работа|работать|удален\p{L}*)[^\n.!?]{0,80}(?:из|в)\s+(?:грузии|georgia)/iu,
  ];
  const restrictedPatterns = [
    /\b(?:remote|work(?:ing)?)\s+(?:only\s+)?within\s+(?:the\s+)?russia\b/i,
    /\bmust\s+be\s+(?:based|located)\s+in\s+(?:the\s+)?russia\b/i,
    /\b(?:russian|russia)\s+residents?\s+only\b/i,
    /(?:работа|работать|удален\p{L}*|оформлен\p{L}*)[^\n.!?]{0,80}только[^\n.!?]{0,40}(?:на\s+территории\s+)?(?:рф|росси\p{L}*)/iu,
    /только[^\n.!?]{0,50}(?:кандидат\p{L}*|сотрудник\p{L}*)[^\n.!?]{0,50}(?:из|в|на\s+территории)\s+(?:рф|росси\p{L}*)/iu,
  ];
  const confirmed = confirmedPatterns.some((pattern) => pattern.test(searchable));
  const restricted = restrictedPatterns.some((pattern) => pattern.test(searchable));

  if (confirmed && !restricted) {
    return {
      value: 'confirmed',
      evidence: ['description_confirms_work_from_georgia'],
    };
  }

  if (restricted && !confirmed) {
    return {
      value: 'restricted',
      evidence: ['description_restricts_work_outside_georgia'],
    };
  }

  return {
    value: 'unknown',
    evidence: confirmed && restricted
      ? ['conflicting_remote_geography_evidence']
      : ['work_from_georgia_not_confirmed'],
  };
}

function salaryFields(vacancy) {
  const salary = vacancy?.salary_range ?? vacancy?.salary ?? null;
  if (!salary || typeof salary !== 'object') {
    return {
      salary_specified: false,
      salary_from: null,
      salary_to: null,
      salary_currency: null,
      salary_gross: null,
      salary_frequency: null,
      salary_formatted: null,
    };
  }

  const from = Number.isFinite(Number(salary.from)) ? Number(salary.from) : null;
  const to = Number.isFinite(Number(salary.to)) ? Number(salary.to) : null;
  const currency = text(salary.currency) || null;
  const range = from !== null && to !== null
    ? `${from}–${to}`
    : from !== null
      ? `от ${from}`
      : to !== null
        ? `до ${to}`
        : '';

  return {
    salary_specified: from !== null || to !== null,
    salary_from: from,
    salary_to: to,
    salary_currency: currency,
    salary_gross: typeof salary.gross === 'boolean' ? salary.gross : null,
    salary_frequency: text(salary.frequency?.id) || null,
    salary_formatted: range ? `${range}${currency ? ` ${currency}` : ''}` : null,
  };
}

const inputItem = $input.item;
const raw = inputItem?.json ?? {};
const preview = upstreamPreview();
const response = normalizedResponse(raw);
const vacancy = response.body ?? {};
const sourceId = text(vacancy.id || preview.source_id);
const title = text(vacancy.name || preview.title);
const description = stripHtml(vacancy.description);
const publicUrl = text(vacancy.alternate_url || preview.url || (sourceId ? `https://hh.ru/vacancy/${sourceId}` : ''));
const area = text(vacancy.area?.name || preview.location);
const addressCity = text(vacancy.address?.city);
const city = addressCity || area || null;
const locations = [...new Set([area, addressCity, text(vacancy.address?.raw)].filter(Boolean))];
const format = workFormat(vacancy);
const remoteGeo = remoteEligibility(format.value, description);
const exp = experienceHint(vacancy.experience?.id || preview.hh_preview_experience_id);
const normalizationErrors = [];

if (response.statusCode < 200 || response.statusCode >= 300) {
  normalizationErrors.push(`hh_http_${response.statusCode}`);
}
if (!sourceId) normalizationErrors.push('source_id_missing');
if (!title) normalizationErrors.push('title_missing');
if (!description) normalizationErrors.push('description_missing');
if (!publicUrl) normalizationErrors.push('url_missing');

const isTbilisi = /(?:тбилиси|tbilisi|თბილისი)/iu.test(locations.join(' '));
const isGeorgia = isTbilisi || /(?:грузи(?:я|и)|georgia|საქართველო)/iu.test(locations.join(' '));

return {
  ...inputItem,
  json: {
    ...preview,
    source: 'headhunter',
    source_id: sourceId || null,
    source_guid: sourceId ? `hh:${sourceId}` : preview.source_guid ?? null,
    source_state_key: preview.source_state_key || (sourceId ? `hh:${sourceId}` : null),
    vacancy_key: sourceId ? `hh:${sourceId}` : preview.vacancy_key ?? null,
    api_url: text(vacancy.url || preview.api_url) || null,
    url: publicUrl || null,
    title: title || null,
    company: text(vacancy.employer?.name || preview.company) || null,
    description,
    skills: stringArray(vacancy.key_skills),
    professional_roles: stringArray(vacancy.professional_roles),
    employment: text(vacancy.employment_form?.name || vacancy.employment?.name) || null,
    experience: text(vacancy.experience?.name || preview.hh_preview_experience_name) || null,
    experience_id: text(vacancy.experience?.id || preview.hh_preview_experience_id) || null,
    experience_min_years_hint: exp.min,
    experience_max_years_hint: exp.max,
    location: locations.join(', ') || null,
    locations,
    city,
    country: isGeorgia ? 'Georgia' : null,
    is_tbilisi: isTbilisi,
    is_georgia: isGeorgia,
    work_format: format.value,
    work_format_confidence: format.confidence,
    work_format_conflict: format.conflict,
    work_format_evidence: format.ids,
    remote_geo_eligibility: remoteGeo.value,
    remote_geo_evidence: remoteGeo.evidence,
    remote_denied: false,
    archived: vacancy.archived === true,
    hidden: vacancy.hidden === true,
    status: vacancy.archived === true ? 'archived' : vacancy.hidden === true ? 'hidden' : 'active',
    published_at: text(vacancy.published_at || preview.published_at) || null,
    created_at: text(vacancy.created_at || preview.created_at) || null,
    ...salaryFields(vacancy),
    predicted_salary_available: false,
    predicted_salary_formatted: null,
    salary_filter_applied: false,
    normalization_ok: normalizationErrors.length === 0,
    normalization_errors: normalizationErrors,
    normalization_warnings: [],
    normalizer_version: HH_NORMALIZER_VERSION,
  },
};

/**
 * MARK — Run Metrics
 * Version: 1.1.0
 * n8n Code node mode: Run Once for All Items
 *
 * The same source is embedded in four metric nodes. Item contract fields
 * identify the stage, so branch execution order cannot misclassify a metric.
 */

const METRICS_VERSION = '1.1.0';
const items = $input.all();
const staticData = $getWorkflowStaticData('global');
const root = staticData.mark_job_hunter ?? (staticData.mark_job_hunter = {});
root.runs ??= {};

const jsonItems = items.map((item) => item?.json ?? {});
let metric = 'rss_items';
if (jsonItems.some((json) => Object.prototype.hasOwnProperty.call(json, 'level_decision'))) {
  metric = 'level_pass_or_stretch';
} else if (jsonItems.some((json) => Object.prototype.hasOwnProperty.call(json, 'hard_filter_decision'))) {
  metric = 'hard_filter_pass';
} else if (jsonItems.some((json) => Object.prototype.hasOwnProperty.call(json, 'prefilter_decision'))) {
  metric = 'prefilter_pass';
}

const run = root.current_run_id ? root.runs[root.current_run_id] : null;
if (run && metric) {
  run.by_source ??= {};
  const source = jsonItems.some((json) => {
    const value = String(json.source ?? '').toLowerCase();
    return value === 'headhunter' || value === 'hh' || String(json.vacancy_key ?? '').startsWith('hh:');
  }) ? 'headhunter' : 'habr';
  run.by_source[source] ??= {};
  run.by_source[source][metric] = items.length;
  run[metric] = Object.values(run.by_source)
    .reduce((total, sourceMetrics) => total + Number(sourceMetrics?.[metric] ?? 0), 0);
  run.metrics_version = METRICS_VERSION;
  run.last_metric_at = new Date().toISOString();
}

return items;

/**
 * MARK — Durable Source Gate
 * Version: 1.2.0
 * n8n Code node mode: Run Once for All Items
 *
 * Prevents the same RSS vacancy from being fetched on every execution. New,
 * due-for-retry, and stale in-progress items pass; completed and terminally
 * failed items stay tracked and are skipped.
 */

const SOURCE_GATE_VERSION = '1.2.0';
const STATE_SCHEMA = 'mark.workflow_state.v1';
const PROCESSING_STALE_MS = 20 * 60 * 1000;
const RETENTION_MS = 60 * 24 * 60 * 60 * 1000;
const MAX_SOURCE_ITEMS = 2000;

const inputItems = $input.all();
const staticData = $getWorkflowStaticData('global');
const root = staticData.mark_job_hunter ?? (staticData.mark_job_hunter = {});

root.schema_version = STATE_SCHEMA;
root.source_items ??= {};
root.vacancies ??= {};
root.runs ??= {};
root.errors ??= [];

const now = Date.now();
const nowIso = new Date(now).toISOString();

function value(...candidates) {
  for (const candidate of candidates) {
    const normalized = String(candidate ?? '').trim();
    if (normalized) return normalized;
  }
  return '';
}

function sourceKey(json) {
  const annotated = value(json.source_state_key);
  if (annotated) return annotated;

  const raw = value(
    json.source_guid,
    json.guid,
    json.vacancy_key,
    json.source_id,
    json.link,
    json.url,
  );
  if (!raw) return '';
  if (/^(?:habr|hh):/i.test(raw)) return raw.toLowerCase().startsWith('hh:') ? `hh:${raw.slice(3)}` : raw;

  const source = value(json.source).toLowerCase();
  const namespace = source === 'headhunter' || source === 'hh' || /(?:api\.)?hh\.ru|headhunter\.ge/i.test(raw)
    ? 'hh'
    : 'habr';
  return `${namespace}:${raw}`;
}

if (now - Number(root.last_source_prune_at_ms ?? 0) > 24 * 60 * 60 * 1000) {
  const records = Object.entries(root.source_items)
    .map(([key, record]) => ({
      key,
      updated: Date.parse(record.updated_at ?? record.first_seen_at ?? 0) || 0,
    }))
    .sort((a, b) => b.updated - a.updated);

  for (const entry of records) {
    if (entry.updated > 0 && now - entry.updated > RETENTION_MS) {
      delete root.source_items[entry.key];
    }
  }

  const remaining = Object.entries(root.source_items)
    .map(([key, record]) => ({
      key,
      updated: Date.parse(record.updated_at ?? record.first_seen_at ?? 0) || 0,
    }))
    .sort((a, b) => b.updated - a.updated);
  for (const entry of remaining.slice(MAX_SOURCE_ITEMS)) {
    delete root.source_items[entry.key];
  }
  root.last_source_prune_at_ms = now;
}

const output = [];
let skipped = 0;

for (const item of inputItems) {
  const json = item?.json ?? {};
  const key = sourceKey(json);

  if (!key) {
    output.push({
      ...item,
      json: {
        ...json,
        workflow_state_schema: STATE_SCHEMA,
        source_gate_version: SOURCE_GATE_VERSION,
        source_state_key: null,
        source_state_action: 'process',
        source_state_reason: 'missing_key_untracked',
      },
    });
    continue;
  }

  const record = root.source_items[key];
  const updatedAt = Date.parse(record?.updated_at ?? 0) || 0;
  const retryDue = record?.status === 'retry' && Number(record.next_retry_at_ms ?? 0) <= now;
  const staleProcessing = record?.status === 'processing' && now - updatedAt >= PROCESSING_STALE_MS;
  const vacancyRecord = record?.vacancy_key ? root.vacancies[record.vacancy_key] : null;
  const downstreamRecoveryDue = Boolean(vacancyRecord) && (
    (
      vacancyRecord.scoring_status === 'error' &&
      Number(vacancyRecord.next_retry_at_ms ?? 0) <= now
    ) ||
    (
      vacancyRecord.scoring_status === 'completed' &&
      vacancyRecord.delivery_required === true &&
      vacancyRecord.telegram_sent !== true
    ) ||
    (
      vacancyRecord.scoring_status === 'pending' &&
      now - (Date.parse(vacancyRecord.updated_at ?? 0) || 0) >= PROCESSING_STALE_MS
    )
  );
  const shouldProcess = !record || retryDue || staleProcessing || downstreamRecoveryDue;

  if (!shouldProcess) {
    skipped += 1;
    continue;
  }

  const reason = !record
    ? 'new_source_item'
    : retryDue
      ? 'source_retry_due'
      : staleProcessing
        ? 'stale_source_processing_recovery'
        : 'downstream_recovery_due';

  root.source_items[key] = {
    ...(record ?? {}),
    key,
    status: 'processing',
    attempts: Number(record?.attempts ?? 0) + 1,
    first_seen_at: record?.first_seen_at ?? nowIso,
    updated_at: nowIso,
    next_retry_at_ms: 0,
    last_reason: reason,
  };

  output.push({
    ...item,
    json: {
      ...json,
      workflow_state_schema: STATE_SCHEMA,
      source_gate_version: SOURCE_GATE_VERSION,
      source_state_key: key,
      source_state_action: 'process',
      source_state_reason: reason,
    },
  });
}

const run = root.current_run_id ? root.runs[root.current_run_id] : null;
if (run) {
  const source = inputItems.some((item) => {
    const json = item?.json ?? {};
    const name = value(json.source).toLowerCase();
    return name === 'headhunter' || name === 'hh' || sourceKey(json).startsWith('hh:');
  }) ? 'headhunter' : 'habr';
  run.by_source ??= {};
  run.by_source[source] ??= {};
  run.by_source[source].new_guid_count = output.length;
  run.by_source[source].source_skipped_count = skipped;
  run.new_guid_count = Object.values(run.by_source)
    .reduce((total, metrics) => total + Number(metrics?.new_guid_count ?? 0), 0);
  run.source_skipped_count = Object.values(run.by_source)
    .reduce((total, metrics) => total + Number(metrics?.source_skipped_count ?? 0), 0);
  run.last_source_gate_at = nowIso;
}

return output;

/**
 * MARK — Habr Career RSS Pre-filter / Classifier
 * Version: 4.0.0-ultimate
 * n8n Code node mode: Run Once for All Items
 *
 * IMPORTANT ARCHITECTURE:
 * - This node returns ALL RSS items for auditability.
 * - Every item gets PASS / REVIEW / REJECT.
 * - Put an n8n Filter node after this node:
 *     should_fetch_full_page is true
 * - Then keep Dev Limit during development.
 *
 * Why:
 * - We do not silently destroy rejected vacancies.
 * - We can inspect false positives / false negatives later.
 * - PASS + REVIEW go to full-page fetch; REJECT stays visible in execution data.
 *
 * Salary is intentionally ignored.
 * Work-location policy is only hinted here; final enforcement belongs to JH-5:
 * - full remote: eligible for full-page fetch; Hard Filter confirms Georgia availability
 * - hybrid: allowed only in Tbilisi, Georgia
 * - office: allowed only in Tbilisi, Georgia
 */

const items = $input.all();

const PREFILTER_VERSION = '4.0.0-ultimate';

// ============================================================
// 1. GENERIC HELPERS
// ============================================================

function decodeHtmlEntities(value) {
  return String(value ?? '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) =>
      String.fromCodePoint(parseInt(code, 16))
    );
}

function htmlToPlainText(value) {
  return decodeHtmlEntities(value)
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function normalizeText(value) {
  return htmlToPlainText(value)
    .normalize('NFKC')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[–—−]/g, '-')
    .replace(/[“”„«»]/g, '"')
    .replace(/[’‘`]/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function uniq(values) {
  return [...new Set(values.filter(Boolean))];
}

function uniqueBy(values, keyFn) {
  const seen = new Set();
  const result = [];

  for (const value of values) {
    const key = keyFn(value);
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(value);
  }

  return result;
}

function matchPatterns(patterns, text) {
  if (!text) return [];
  return patterns.filter((pattern) => pattern.regex.test(text));
}

function names(matches) {
  return uniq(matches.map((match) => match.name));
}

function categories(matches) {
  return uniq(matches.map((match) => match.category));
}

function hasAny(patterns, text) {
  if (!text) return false;
  return patterns.some((pattern) => (pattern.regex ?? pattern).test(text));
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function countIntersection(values, set) {
  return values.filter((value) => set.has(value)).length;
}

function bestTier(tiers) {
  if (tiers.includes('A')) return 'A';
  if (tiers.includes('B')) return 'B';
  if (tiers.includes('C')) return 'C';
  return null;
}

function decisionRank(decision) {
  if (decision === 'PASS') return 0;
  if (decision === 'REVIEW') return 1;
  return 2;
}

// ============================================================
// 2. HABR RSS STRUCTURE PARSER
// ============================================================

/**
 * Habr RSS usually looks like:
 * "Компания «X» ищет хорошего специалиста на вакансию «Y».
 *  Полный рабочий день. Можно удалённо.
 *  Требуемые навыки: #Python, #LLM, #LangGraph."
 *
 * We parse structured hints instead of treating the whole text as one blob.
 */
function extractVacancyTitle(rawTitle, rawContent) {
  const title = htmlToPlainText(rawTitle).trim();
  const content = htmlToPlainText(rawContent).trim();

  const titlePatterns = [
    /^требуется\s+[«"](.+?)[»"]\s*$/iu,
    /^вакансия\s+[«"](.+?)[»"]\s*$/iu,
    /^ищем\s+[«"]?(.+?)[»"]?\s*$/iu,
  ];

  for (const pattern of titlePatterns) {
    const match = title.match(pattern);
    if (match?.[1]) return match[1].trim();
  }

  const contentMatch = content.match(
    /(?:на\s+ваканси(?:ю|и)|вакансия)\s+[«"](.+?)[»"]/iu
  );

  if (contentMatch?.[1]) return contentMatch[1].trim();

  return title;
}

function extractRssSkills(rawContent) {
  const text = htmlToPlainText(rawContent);

  const markers = [
    /требуемые\s+навыки\s*:\s*([^\n]+)$/iu,
    /навыки\s*:\s*([^\n]+)$/iu,
    /required\s+skills\s*:\s*([^\n]+)$/iu,
  ];

  let skillsPart = null;

  for (const marker of markers) {
    const match = text.match(marker);
    if (match?.[1]) {
      skillsPart = match[1].trim();
      break;
    }
  }

  if (!skillsPart) return [];

  skillsPart = skillsPart.replace(/[.!?]+\s*$/u, '').trim();

  return uniq(
    skillsPart
      .split(/\s*,\s*/u)
      .map((skill) => skill.replace(/^#+/u, '').trim())
      .filter(Boolean)
  );
}

function extractRssNarrative(rawContent) {
  let text = htmlToPlainText(rawContent);

  // Remove the skills tail so skills can be weighted separately.
  text = text.replace(
    /(?:требуемые\s+навыки|required\s+skills|навыки)\s*:[\s\S]*$/iu,
    ' '
  );

  // Remove common Habr boilerplate with company/title duplication.
  text = text.replace(
    /^компания\s+[«"].+?[»"]\s+ищет\s+хорошего\s+специалиста\s+на\s+вакансию\s+[«"].+?[»"]\.?\s*/iu,
    ' '
  );

  return normalizeText(text);
}

function parseHabrRss(itemJson) {
  const rawTitle = String(itemJson.title ?? '');
  const rawContent = String(itemJson.content ?? itemJson.contentSnippet ?? '');

  const vacancyTitle = extractVacancyTitle(rawTitle, rawContent);
  const skills = extractRssSkills(rawContent);

  return {
    vacancy_title_raw: vacancyTitle,
    vacancy_title_normalized: normalizeText(vacancyTitle),
    rss_skills: skills,
    rss_skills_normalized: skills.map(normalizeText),
    rss_skills_text: normalizeText(skills.join(' ')),
    rss_narrative_text: extractRssNarrative(rawContent),
    rss_full_text: normalizeText(rawContent),
  };
}

